#include "resource/qrx_storage_market.h"
#include <assert.h>
int main(void){QrxStorageProviderReputation r;qrx_storage_reputation_init(&r);assert(r.reputation_bps==8000);for(int i=0;i<20;i++)assert(qrx_storage_reputation_record_proof(&r,1,11500)==0);assert(r.reputation_bps>8000&&r.performance_bps<=11500);for(int i=0;i<10;i++)assert(qrx_storage_reputation_record_proof(&r,0,5000)==0);assert(r.proofs_failed==10);uint64_t cap=4ULL*1024*1024*1024*1024,bond=qrx_storage_required_bond(cap);QrxStorageBondState bs;assert(qrx_storage_bond_register(&bs,cap,bond)==0);assert(qrx_storage_bond_activate(&bs)==0);bs.allocated_bytes=1;assert(qrx_storage_bond_begin_exit(&bs,100)==0);assert(!qrx_storage_bond_withdrawable(&bs,100+QRX_STORAGE_EXIT_DELAY_BLOCKS));bs.allocated_bytes=0;assert(qrx_storage_bond_withdrawable(&bs,100+QRX_STORAGE_EXIT_DELAY_BLOCKS));uint64_t back=0;assert(qrx_storage_bond_withdraw(&bs,100+QRX_STORAGE_EXIT_DELAY_BLOCKS,&back)==0&&back==bond);QrxStorageFinancialState f;assert(qrx_storage_financial_init(1000000,&f)==0);assert(f.development_atoms==5000&&f.resilience_atoms==20000&&f.provider_escrow_atoms==975000);QrxStorageRewardInput in={1024ULL*1024*1024,1,10000,10000,10000,11500};uint64_t reward=qrx_storage_provider_reward(&in);assert(reward==11500);assert(qrx_storage_financial_pay_provider(&f,reward)==0);assert(qrx_storage_financial_pay_repair(&f,5000)==0);assert(qrx_storage_financial_pay_egress(&f,1000)==0);assert(qrx_storage_financial_refundable(&f)==1000000-5000-reward-5000-1000);return 0;}
